"use client";
import { useMemo, useState } from "react";
type Bucket = "exit" | "name" | "dob" | "kyc" | "bank" | "employer" | "form" | "transfer" | "unclear";
type D={title:string;summary:string;steps:string[];docs:string[];hr:string;grievance:string;share:string};
const D:Record<Bucket,D>={
exit:{title:"Your date of exit probably isn’t recorded",summary:"EPFO needs your last working date before it can process a final settlement or transfer.",steps:["Check Service History in the EPFO portal.","Ask your previous employer to update the date of exit and reason.","Wait 3–5 working days, then retry if needed."],docs:["Last payslip","Service history screenshot","Relieving letter"],hr:"Subject: Please update my EPFO date of exit\\n\\nHi HR,\\n\\nMy EPFO service history is missing my date of exit for [COMPANY]. Please update it in the employer portal. Name: [NAME] | Member ID: [MEMBER ID] | Last working day: [DATE]\\n\\nThanks,\\n[NAME]",grievance:"My EPFO claim is blocked because the date of exit for my previous employment is missing or incorrect. Please ask the employer to update it and enable processing. Employer: [COMPANY].",share:"My PF claim was stuck because my date of exit wasn’t updated. This free tool gave me a ready HR email + EPFiGMS draft: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
name:{title:"Your name may not match across records",summary:"Initials, spacing, surname order or a typo can make EPFO treat your records as different people.",steps:["Compare EPFO with Aadhaar and PAN.","Ask HR to correct the EPFO member profile to match the correct government record.","Retry KYC or the claim after approval."],docs:["Aadhaar (masked)","PAN card","EPFO profile screenshot"],hr:"Subject: Request to correct name in EPFO records\\n\\nHi HR,\\n\\nPlease correct my EPFO member name to [CORRECT NAME] so it matches Aadhaar. Current name: [CURRENT NAME]. Member ID: [MEMBER ID].\\n\\nThanks,\\n[NAME]",grievance:"My EPFO records have a name mismatch with Aadhaar, preventing my claim. Please advise the correction route. Current: [CURRENT]. Correct: [CORRECT].",share:"PF claim stuck because of a name mismatch? I got the HR email + EPFiGMS draft I needed: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
dob:{title:"Your date of birth may be mismatched",summary:"A different DOB in EPFO, Aadhaar or PAN can stop KYC validation and claim processing.",steps:["Compare DOB across EPFO, Aadhaar and PAN.","Ask HR to raise profile correction using the correct proof. Do not create another UAN.","Recheck KYC after approval."],docs:["Aadhaar","PAN","DOB proof if requested"],hr:"Subject: Request to correct DOB in EPFO records\\n\\nHi HR,\\n\\nMy EPFO date of birth is incorrect. Please initiate correction to [DD/MM/YYYY]. Member ID: [MEMBER ID]. Proof attached.\\n\\nThanks,\\n[NAME]",grievance:"My claim is blocked due to a DOB mismatch in EPFO. Please guide correction and reprocess it. Correct DOB: [DD/MM/YYYY].",share:"A DOB mismatch was why my PF claim stalled. Ready-to-send HR email and grievance: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
kyc:{title:"Your KYC is not approved yet",summary:"Aadhaar, PAN or bank KYC can be seeded but still pending employer approval.",steps:["Open Manage → KYC and note which item is Pending.","Ask HR to approve that exact item in the employer portal.","Check again after 3–7 working days."],docs:["KYC screenshot","Relevant Aadhaar / PAN / cheque","Last payslip"],hr:"Subject: Please approve my pending EPFO KYC\\n\\nHi HR,\\n\\nMy EPFO [AADHAAR / PAN / BANK] KYC is pending employer approval. Please approve it so I can process my PF claim. Name: [NAME] | Member ID: [MEMBER ID].\\n\\nThanks,\\n[NAME]",grievance:"My [AADHAAR / PAN / BANK] KYC is pending employer approval and blocking my claim. Please facilitate approval or advise the next action.",share:"My PF was waiting on employer KYC approval. This tool gave me the nudge email and grievance text: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
bank:{title:"Your bank account or IFSC needs attention",summary:"A closed account, name mismatch, wrong IFSC or unapproved bank KYC can bounce a claim.",steps:["Verify the account is active and in your name; check the latest IFSC.","Update bank KYC with a clear cancelled cheque if requested.","Wait for approval, then retry. Never share OTPs or passwords."],docs:["Cancelled cheque","Passbook front page","IFSC confirmation"],hr:"Subject: Please approve corrected EPFO bank KYC\\n\\nHi HR,\\n\\nI updated my EPFO bank details because [ISSUE]. Please approve the new bank KYC. Name: [NAME] | Member ID: [MEMBER ID] | Last 4 digits: [1234].\\n\\nThanks,\\n[NAME]",grievance:"My EPFO claim payment is blocked because bank details or IFSC validation failed. I updated the active account and request verification and reprocessing.",share:"Bank/IFSC error holding up your PF? I found the exact checklist and HR note here: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
 employer:{title:"Your employer is the bottleneck",summary:"If HR is silent or the company is closed, document the trail and escalate instead of waiting forever.",steps:["Send one clear request to HR, payroll and your manager with a deadline.","Keep sent email and delivery proof; after 7 working days file EPFiGMS.","If the employer is closed, attach relieving or salary proof."],docs:["HR email proof","Relieving letter / payslips","Service history"],hr:"Subject: Urgent EPFO action needed by [DATE]\\n\\nHi HR / PAYROLL,\\n\\nPlease complete this EPFO action: [EXACT ACTION]. My claim is blocked because [REASON]. Name: [NAME] | Member ID: [MEMBER ID].\\n\\nThanks,\\n[NAME]",grievance:"My previous employer has not completed the EPFO action needed for my claim: [EXACT ACTION]. I contacted them on [DATES] with no resolution. Please intervene.",share:"When HR goes silent, document it and escalate. This PF tool gave me a clean HR follow-up + EPFiGMS draft: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
 form:{title:"You may be in an EPS / form waiting period",summary:"Forms 19, 10C, 10D and scheme certificates have different eligibility and processing paths.",steps:["Identify whether this is final settlement, pension withdrawal benefit or scheme certificate.","Check total service and whether you are currently employed.","Ask EPFO through EPFiGMS for the exact form before resubmitting."],docs:["Claim rejection text","Service history","Previous claim acknowledgement"],hr:"Subject: Please confirm correct EPFO claim form\\n\\nHi HR,\\n\\nMy claim was returned with: [PASTE NOTE]. Please confirm whether I should use Form 19, 10C, 10D or another route. Name: [NAME] | Member ID: [MEMBER ID].\\n\\nThanks,\\n[NAME]",grievance:"My EPFO claim was returned and I need clarification on the correct claim type based on my service history. Please provide the correct route and reason.",share:"Not every PF claim uses the same form. I used this diagnostic to figure out my EPS/form wait: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
 transfer:{title:"Your PF transfer is still in the chain",summary:"A transfer can pause when the previous account, exit date, attestation or service history is not aligned.",steps:["Check whether the current or previous employer is expected to act.","Confirm both member IDs have matching details, approved KYC and an exit date.","If beyond the processing window, raise EPFiGMS with claim ID."],docs:["Transfer claim screenshot","Both member IDs (mask publicly)","Annexure K if available"],hr:"Subject: Please action my pending PF transfer\\n\\nHi HR,\\n\\nMy PF transfer from [PREVIOUS COMPANY] is pending. Please check whether attestation or service-history correction is required. Transfer ID: [ID] | Member ID: [MEMBER ID].\\n\\nThanks,\\n[NAME]",grievance:"My PF transfer claim [CLAIM ID] has been pending since [DATE]. Please check the transfer chain and complete the pending action.",share:"PF transfer stuck? The blocker is usually somewhere in the chain. Checklist + grievance: https://sandeshl702.github.io/why-is-my-pf-stuck/"},
 unclear:{title:"There’s not enough signal yet",summary:"Paste the exact EPFO status or rejection text for a sharper answer. Start with universal checks meanwhile.",steps:["Copy the exact status or rejection reason; remove Aadhaar, bank numbers and sensitive details.","Check date of exit, KYC, name/DOB and bank details in that order.","If beyond the expected window, raise EPFiGMS with claim ID and timeline."],docs:["Exact status text","Service history screenshot","Claim acknowledgement"],hr:"Subject: Help me identify the EPFO claim blocker\\n\\nHi HR,\\n\\nMy claim shows: [PASTE STATUS]. Please confirm whether the issue is date of exit, KYC, member details, bank details or claim type. Name: [NAME] | Member ID: [MEMBER ID].\\n\\nThanks,\\n[NAME]",grievance:"My EPFO claim shows: [PASTE STATUS]. Please confirm the specific blocker, responsible party and action required. Claim ID: [ID].",share:"I used a free PF diagnostic to turn a confusing EPFO status into next steps, an HR email and EPFiGMS draft: https://sandeshl702.github.io/why-is-my-pf-stuck/"}
};
const options={exit:"Date of exit missing",name:"Name mismatch",dob:"DOB mismatch",kyc:"KYC pending",bank:"Bank / IFSC error",employer:"Employer silent / closed",form:"Wrong form / EPS wait",transfer:"Transfer stuck"} as const;
const words:[Bucket,string[]][]=[["exit",["date of exit","doe","exit date","last working","service history"]],["name",["name mismatch","name does not match","wrong name"]],["dob",["dob","date of birth","birth"]],["kyc",["kyc","aadhaar pending","pan pending","employer approval"]],["bank",["bank","ifsc","account number","payment failed"]],["employer",["employer not","employer silent","company closed","hr not"]],["form",["10c","10d","form 19","eps","scheme certificate","wrong form"]],["transfer",["transfer","annexure k","previous account","member id"]]];
function detect(t:string):Bucket{const s=t.toLowerCase();for(const [b,w] of words)if(w.some(x=>s.includes(x)))return b;return "unclear"}
function copy(t:string,set:(s:string)=>void,label:string){navigator.clipboard?.writeText(t);set(label);setTimeout(()=>set(""),1800)}
export default function Home(){
 const [text,setText]=useState(""); const [picked,setPicked]=useState<Bucket|null>(null); const [result,setResult]=useState<Bucket|null>(null); const [copied,setCopied]=useState(""); const [launch,setLaunch]=useState(false);
 const d=useMemo(()=>D[result||"unclear"],[result]);
 const reset=()=>{setResult(null);setPicked(null);setText("");setLaunch(false);window.scrollTo({top:0,behavior:"smooth"})};
 const share=async()=>{const t=d.share;if(navigator.share)await navigator.share({title:"Why is my PF stuck?",text:t,url:"https://sandeshl702.github.io/why-is-my-pf-stuck/"});else copy(t,setCopied,"Post copied")};
 return <main>
  <nav className="mx-auto flex max-w-6xl items-center justify-between px-5 py-6"><a href="/why-is-my-pf-stuck/" className="flex items-center gap-2 font-black tracking-tight"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[#d9f99d] text-xl rough-border">?</span>WHY IS MY <span className="text-orange-600">PF</span> STUCK?</a><div className="hidden gap-5 text-sm font-bold text-[#58736b] sm:flex"><a href="#how">How it works</a><a href="#launch">Launch kit</a><a href="https://epfigms.gov.in/" target="_blank">Official EPFiGMS ↗</a></div></nav>
  {!result?<Landing text={text} setText={setText} picked={picked} setPicked={setPicked} diagnose={()=>setResult(picked||detect(text))}/>:<Result d={d} copied={copied} setCopied={setCopied} share={share} reset={reset} launch={launch} setLaunch={setLaunch}/>} 
 </main>
}
function Landing({text,setText,picked,setPicked,diagnose}:{text:string;setText:(s:string)=>void;picked:Bucket|null;setPicked:(b:Bucket)=>void;diagnose:()=>void}){return <>
 <section className="paper-grid border-y-2 border-[#12312b] px-5 py-16 sm:py-24"><div className="mx-auto max-w-5xl"><div className="max-w-3xl"><div className="mb-6 inline-flex rotate-[-2deg] rounded-full border-2 border-[#12312b] bg-[#fcd34d] px-4 py-2 text-xs font-black uppercase tracking-[.16em]">No login · no UAN · no uploads</div><h1 className="text-5xl font-black leading-[.94] tracking-[-.06em] sm:text-8xl">Find the blocker.<br/><span className="text-orange-600">Fix the stuck.</span></h1><p className="mt-7 max-w-xl text-lg font-medium leading-relaxed text-[#58736b] sm:text-xl">Paste what EPFO told you—or pick a symptom. Get a plain-English diagnosis and a fix pack you can actually send.</p></div><div className="mt-12 grid gap-5 lg:grid-cols-[1.4fr_1fr]"><div className="rounded-3xl bg-white p-5 rough-border sm:p-7"><label htmlFor="rejection" className="mb-3 block text-sm font-black uppercase tracking-wider">Paste rejection / status text <span className="font-medium normal-case text-[#58736b]">(optional)</span></label><textarea id="rejection" value={text} onChange={e=>setText(e.target.value)} placeholder="e.g. Claim rejected: Date of Exit is not available..." className="min-h-36 w-full resize-y rounded-2xl border-2 border-[#b4c6bc] bg-[#fcfcf8] p-4 text-base outline-none focus:border-[#12312b] focus:ring-4 focus:ring-[#d9f99d]"/><p className="mt-3 text-xs text-[#58736b]">Tip: remove Aadhaar, bank numbers and other sensitive details.</p></div><div className="rounded-3xl bg-[#12312b] p-5 text-white sm:p-7"><p className="mb-4 text-sm font-black uppercase tracking-wider text-[#d9f99d]">Or pick what feels closest</p><div className="grid grid-cols-2 gap-2">{Object.entries(options).map(([b,label])=><button key={b} onClick={()=>setPicked(b as Bucket)} className={`rounded-xl border-2 px-3 py-3 text-left text-sm font-bold transition ${picked===b?"border-[#d9f99d] bg-[#d9f99d] text-[#12312b]":"border-[#49675e] text-white hover:border-white"}`}>{label}</button>)}</div></div></div><button onClick={diagnose} className="mt-6 rounded-full bg-orange-600 px-8 py-4 text-base font-black text-white shadow-[4px_4px_0_#12312b]">Diagnose my PF →</button></div></section><How/><Launch/></>}
function How(){return <section id="how" className="mx-auto max-w-6xl px-5 py-20"><div className="mb-10"><p className="mb-2 text-sm font-black uppercase tracking-[.16em] text-orange-600">Three tiny moves</p><h2 className="text-4xl font-black tracking-tight sm:text-5xl">Less guessing.<br/>More getting unstuck.</h2></div><div className="grid gap-4 md:grid-cols-3">{[["01","Drop the clue","Paste the exact EPFO line or tap the symptom that matches."],["02","Get the fix pack","See the likely blocker, next steps and a docs checklist."],["03","Make the ask","Copy a ready HR email or an EPFiGMS grievance draft."]].map(([n,t,d])=><div key={n} className="card-hover rounded-3xl border-2 border-[#12312b] bg-white p-6"><span className="text-5xl font-black text-[#d4e4da]">{n}</span><h3 className="mt-7 text-xl font-black">{t}</h3><p className="mt-2 leading-relaxed text-[#58736b]">{d}</p></div>)}</div></section>}
function Launch(){const post="My PF claim was stuck because I was looking at the wrong thing. This free tool helped me identify the blocker and gave me a ready HR email + EPFiGMS draft. No login, no UAN. Try it: https://sandeshl702.github.io/why-is-my-pf-stuck/";return <section id="launch" className="border-t-2 border-[#12312b] bg-[#d9f99d] px-5 py-16"><div className="mx-auto max-w-6xl"><p className="mb-2 text-sm font-black uppercase tracking-[.16em]">Built to be passed on</p><h2 className="max-w-xl text-4xl font-black tracking-tight sm:text-5xl">Your PF story might save someone else a week.</h2><div className="mt-10 grid gap-4 md:grid-cols-2"><div className="rounded-3xl border-2 border-[#12312b] bg-[#f7f5ef] p-6"><p className="mb-3 text-xs font-black uppercase tracking-widest">LinkedIn post</p><p className="text-lg font-bold leading-relaxed">{post}</p><button onClick={()=>navigator.clipboard?.writeText(post)} className="mt-5 rounded-full bg-[#12312b] px-5 py-3 text-sm font-black text-white">Copy post</button></div><div className="rounded-3xl border-2 border-[#12312b] bg-[#12312b] p-6 text-white"><p className="mb-3 text-xs font-black uppercase tracking-widest text-[#d9f99d]">Carousel slide copy</p><ol className="space-y-3 text-lg font-bold"><li>01 · PF stuck?</li><li>02 · Find the blocker.</li><li>03 · Get the exact ask.</li><li>04 · Move on.</li></ol></div></div></div></section>}
function Result({d,copied,setCopied,share,reset,launch,setLaunch}:{d:D;copied:string;setCopied:(s:string)=>void;share:()=>Promise<void>;reset:()=>void;launch:boolean;setLaunch:(b:boolean)=>void}){return <><section className="border-b-2 border-[#12312b] bg-[#12312b] px-5 py-14 text-white sm:py-20"><div className="mx-auto max-w-5xl"><button onClick={reset} className="mb-12 text-sm font-bold text-[#d9f99d]">← Diagnose another</button><div className="max-w-3xl"><p className="mb-4 text-sm font-black uppercase tracking-[.16em] text-[#d9f99d]">Diagnosis · practical starting point</p><h1 className="text-5xl font-black leading-[.95] tracking-[-.05em] sm:text-7xl">{d.title}</h1><p className="mt-6 max-w-2xl text-lg leading-relaxed text-[#d3e2da]">{d.summary}</p></div><div className="mt-9 flex flex-wrap gap-3"><button onClick={share} className="rounded-full bg-[#d9f99d] px-5 py-3 text-sm font-black text-[#12312b]">↗ Share result</button><button onClick={()=>setLaunch(!launch)} className="rounded-full border-2 border-[#719084] px-5 py-3 text-sm font-black text-white">{launch?"Hide launch kit":"Copy LinkedIn post"}</button></div></div></section><section className="mx-auto max-w-5xl px-5 py-12 sm:py-16"><div className="grid gap-5 lg:grid-cols-[.85fr_1.5fr]"><div><div className="rounded-3xl border-2 border-[#12312b] bg-[#fcd34d] p-6"><p className="mb-4 text-xs font-black uppercase tracking-widest">Keep these ready</p><ul className="space-y-3">{d.docs.map(x=><li key={x} className="flex gap-2 text-sm font-bold"><span>□</span>{x}</li>)}</ul></div><div className="mt-5 rounded-3xl border-2 border-[#12312b] bg-white p-6 text-sm leading-relaxed text-[#58736b]"><b className="text-[#12312b]">Privacy nudge</b><br/>Never paste your UAN, Aadhaar number, bank account number, OTP or password here. This tool runs in your browser and does not ask for them.</div></div><div><h2 className="mb-5 text-3xl font-black tracking-tight">Your fix pack</h2><div className="space-y-4"><div className="rounded-3xl border-2 border-[#12312b] bg-white p-6"><p className="mb-4 text-xs font-black uppercase tracking-widest text-orange-600">Do this next</p><ol className="space-y-4">{d.steps.map((s,i)=><li key={s} className="flex gap-4"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-[#d9f99d] text-sm font-black">{i+1}</span><span className="leading-relaxed text-[#41625a]">{s}</span></li>)}</ol></div><CopyCard title="Ready-to-send HR email" text={d.hr} copied={copied} setCopied={setCopied} label="HR email copied"/><CopyCard title="EPFiGMS grievance draft" text={d.grievance} copied={copied} setCopied={setCopied} label="Grievance copied"/></div></div></div>{launch&&<div className="mt-8 rounded-3xl border-2 border-[#12312b] bg-[#d9f99d] p-6"><p className="mb-3 text-xs font-black uppercase tracking-widest">Your shareable LinkedIn post</p><p className="max-w-3xl text-lg font-bold leading-relaxed">{d.share}</p><button onClick={()=>copy(d.share,setCopied,"Post copied")} className="mt-5 rounded-full bg-[#12312b] px-5 py-3 text-sm font-black text-white">{copied==="Post copied"?"Copied ✓":"Copy LinkedIn post"}</button></div>}</section></>}
function CopyCard({title,text,copied,setCopied,label}:{title:string;text:string;copied:string;setCopied:(s:string)=>void;label:string}){return <div className="rounded-3xl border-2 border-[#12312b] bg-[#12312b] p-6 text-white"><div className="mb-4 flex items-center justify-between gap-3"><p className="text-xs font-black uppercase tracking-widest text-[#d9f99d]">{title}</p><button onClick={()=>copy(text,setCopied,label)} className="rounded-full border border-[#719084] px-3 py-2 text-xs font-black">{copied===label?"Copied ✓":"Copy"}</button></div><pre className="whitespace-pre-wrap font-sans text-sm leading-relaxed text-[#d3e2da]">{text}</pre></div>}
